/* insertFestivalInfo */
INSERT INTO FESTIVAL_INFO (
    REGN_ID
    , TITLE
    , EVENT_START_DATE
    , EVENT_END_DATE
    , ADDR1
    , ADDR2
    , MAPX
    , MAPY
    , TEL
    , THUMBNAIL
    , HOMEPAGE_URL
    , API_TYPE
)
VALUES (
    #{regnId}
    , #{title}
    , #{eventStartDate}
    , #{eventEndDate}
    , #{addr1}
    , #{addr2}
    , #{mapx}
    , #{mapy}
    , #{tel}
    , #{thumbnail}
    , #{homepageUrl}
    , #{apiType}
)
